 26	package br.com.loja.order;
 27	
 28	import java.time.Clock;
 29	import java.time.Duration;
 30	import java.time.Instant;
 31	import java.time.temporal.ChronoUnit;
 32	import java.util.List;
 33	import java.util.UUID;
 34	
 35	import org.springframework.dao.DuplicateKeyException;
 36	import org.springframework.http.HttpStatus;
 37	import org.springframework.stereotype.Service;
 38	import org.springframework.transaction.PlatformTransactionManager;
 39	import org.springframework.transaction.support.TransactionTemplate;
 40	
 41	import br.com.loja.catalog.ProductRepository;
 42	import br.com.loja.checkout.CheckoutRequest;
 43	import br.com.loja.checkout.CheckoutService;
 44	import br.com.loja.checkout.OrderSummary;
 45	import br.com.loja.common.ApiException;
 46	import br.com.loja.common.ErrorCode;
 47	import br.com.loja.customer.CustomerRepository;
 48	
 49	@Service
 50	public class OrderService {
 51	
 52	    private static final String OK = "OK";
 53	    private static final Duration PAYMENT_WINDOW = Duration.ofHours(48);
 54	
 55	    private final CheckoutService checkout;
 56	    private final OrderRepository orders;
 57	    private final ProductRepository products;
 58	    private final CustomerRepository customers;
 59	    private final List<OrderEventListener> listeners;
 60	    private final Clock clock;
 61	    private final TransactionTemplate tx;
 62	
 63	    OrderService(CheckoutService checkout, OrderRepository orders, ProductRepository products,
 64	                 CustomerRepository customers, List<OrderEventListener> listeners, Clock clock,
 65	                 PlatformTransactionManager transactionManager) {
 66	        this.checkout = checkout;
 67	        this.orders = orders;
 68	        this.products = products;
 69	        this.customers = customers;
 70	        this.listeners = listeners;
 71	        this.clock = clock;
 72	        this.tx = new TransactionTemplate(transactionManager);
 73	    }
 74	
 75	    public Order create(CheckoutRequest request) {
 76	        OrderSummary summary = checkout.summarize(request);
 77	        List<OrderItem> items = request.items().stream()
 78	                .map(i -> new OrderItem(i.sku(), i.quantity())).toList();
 79	        Order order = new Order(UUID.randomUUID().toString(), request.customer().cpf(),
 80	                OrderStatus.AWAITING_PAYMENT, Instant.now(clock).truncatedTo(ChronoUnit.SECONDS), summary, items,
 81	                null, null, null);
 82	        try {
 83	            tx.executeWithoutResult(s -> customers.createIfAbsent(request.customer().cpf(), request.customer().email()));
 84	        } catch (DuplicateKeyException e) {
 85	            // outra máquina criou o mesmo cliente agora há pouco: está tudo certo
 86	        }
 87	        tx.executeWithoutResult(s -> orders.insert(order));
 88	        return order;
 89	    }
 90	
 91	    public Order get(String id) {
 92	        return orders.findById(id).orElseThrow(() -> new ApiException(ErrorCode.ORDER_NOT_FOUND));
 93	    }
 94	
 95	    private record PaymentResult(Order order, ErrorCode error) {
 96	    }
 97	
 98	    public Order confirmPayment(String id, String transactionId, String paidAtText) {
 99	        PaymentResult result = tx.execute(s -> processPayment(id, transactionId, paidAtText));
100	        if (result.error() != null) {
101	            throw new ApiException(result.error(), HttpStatus.CONFLICT);
102	        }
103	        return result.order();
104	    }
105	
106	    private PaymentResult processPayment(String id, String transactionId, String paidAtText) {
107	        Order order = lock(id);
108	        Instant paidAt = parseInstant(paidAtText);
109	        if (transactionId == null || transactionId.isBlank() || paidAt == null) {
110	            throw new ApiException(ErrorCode.INVALID_ORDER);
111	        }
112	        if (transactionId.equals(order.paymentTransactionId())) {
113	            return outcomeOf(order, order.paymentOutcome());
114	        }
115	        requireMove(order, OrderStatus.PAID);
116	
117	        if (paidAt.isAfter(order.createdAt().plus(PAYMENT_WINDOW))) {
118	            return failPayment(order, transactionId, ErrorCode.ORDER_EXPIRED);
119	        }
120	        if (!products.reserve(order.items())) {
121	            return failPayment(order, transactionId, ErrorCode.INSUFFICIENT_STOCK);
122	        }
123	        orders.recordPayment(id, transactionId, OK, OrderStatus.PAID);
124	        Order paid = get(id);
125	        listeners.forEach(l -> l.onPaid(paid));
126	        return new PaymentResult(paid, null);
127	    }
128	
129	    private PaymentResult failPayment(Order order, String transactionId, ErrorCode error) {
130	        orders.recordPayment(order.id(), transactionId, error.name(), OrderStatus.CANCELLED);
131	        Order cancelled = get(order.id());
132	        listeners.forEach(l -> l.onCancelled(cancelled, false));
133	        return new PaymentResult(cancelled, error);
134	    }
135	
136	    private static PaymentResult outcomeOf(Order order, String outcome) {
137	        return new PaymentResult(order, OK.equals(outcome) ? null : ErrorCode.valueOf(outcome));
138	    }
139	
140	    public Order ship(String id, String trackingCode) {
141	        return tx.execute(s -> {
142	            Order order = lock(id);
143	            if (trackingCode == null || trackingCode.isBlank()) {
144	                throw new ApiException(ErrorCode.INVALID_ORDER);
145	            }
146	            requireMove(order, OrderStatus.SHIPPED);
147	            orders.recordShipment(id, trackingCode);
148	            Order shipped = get(id);
149	            listeners.forEach(l -> l.onShipped(shipped));
150	            return shipped;
151	        });
152	    }
153	
154	    public Order deliver(String id) {
155	        return tx.execute(s -> {
156	            Order order = lock(id);
157	            requireMove(order, OrderStatus.DELIVERED);
158	            orders.updateStatus(id, OrderStatus.DELIVERED);
159	            return get(id);
160	        });
161	    }
162	
163	    public Order cancel(String id) {
164	        return tx.execute(s -> {
165	            Order order = lock(id);
166	            requireMove(order, OrderStatus.CANCELLED);
167	            boolean wasPaid = order.status() == OrderStatus.PAID;
168	            if (wasPaid) {
169	                products.release(order.items());
170	            }
171	            orders.updateStatus(id, OrderStatus.CANCELLED);
172	            Order cancelled = get(id);
173	            listeners.forEach(l -> l.onCancelled(cancelled, wasPaid));
174	            return cancelled;
175	        });
176	    }
177	
178	    private Order lock(String id) {
179	        return orders.findByIdForUpdate(id).orElseThrow(() -> new ApiException(ErrorCode.ORDER_NOT_FOUND));
180	    }
181	
182	    private static void requireMove(Order order, OrderStatus target) {
183	        if (!order.status().canMoveTo(target)) {
184	            throw new ApiException(ErrorCode.OPERATION_NOT_ALLOWED);
185	        }
186	    }
187	
188	    private static Instant parseInstant(String text) {
189	        try {
190	            return text == null ? null : Instant.parse(text);
191	        } catch (java.time.format.DateTimeParseException e) {
192	            return null;
193	        }
194	    }
195	}

