 20	import org.springframework.stereotype.Component;
 21	
 22	import br.com.loja.order.Order;
 23	import br.com.loja.order.OrderEventListener;
 24	
 25	/** Entra com o crédito do clube quando o pagamento é confirmado e tira de volta se o pedido pago é cancelado. */
 26	@Component
 27	class LoyaltyCreditListener implements OrderEventListener {
 28	
 29	    private final CustomerRepository customers;
 30	
 31	    LoyaltyCreditListener(CustomerRepository customers) {
 32	        this.customers = customers;
 33	    }
 34	
 35	    @Override
 36	    public void onPaid(Order order) {
 37	        customers.addCredit(order.customerCpf(), order.summary().nextPurchaseCredit());
 38	    }
 39	
 40	    @Override
 41	    public void onCancelled(Order order, boolean wasPaid) {
 42	        if (wasPaid) {
 43	            customers.addCredit(order.customerCpf(), order.summary().nextPurchaseCredit().negate());
 44	        }
 45	    }
 46	}
