126	
127	import java.util.List;
128	import java.util.Optional;
129	
130	import org.springframework.jdbc.core.simple.JdbcClient;
131	import org.springframework.stereotype.Repository;
132	
133	@Repository
134	public class NotificationRepository {
135	
136	    private final JdbcClient jdbc;
137	
138	    NotificationRepository(JdbcClient jdbc) {
139	        this.jdbc = jdbc;
140	    }
141	
142	    public void create(String cpf, String type, String orderId) {
143	        jdbc.sql("INSERT INTO notifications (customer_cpf, type, order_id, status) VALUES (:cpf, :type, :order, 'NEW')")
144	                .param("cpf", cpf).param("type", type).param("order", orderId).update();
145	    }
146	
147	    public List<Notification> findByCustomer(String cpf) {
148	        return jdbc.sql("SELECT id, type, order_id, status FROM notifications WHERE customer_cpf = :cpf ORDER BY id")
149	                .param("cpf", cpf).query(this::map).list();
150	    }
151	
152	    public Optional<Notification> markRead(long id) {
153	        jdbc.sql("UPDATE notifications SET status = 'READ' WHERE id = :id").param("id", id).update();
154	        return jdbc.sql("SELECT id, type, order_id, status FROM notifications WHERE id = :id")
155	                .param("id", id).query(this::map).optional();
156	    }
157	
158	    private Notification map(java.sql.ResultSet rs, int n) throws java.sql.SQLException {
159	        return new Notification(rs.getLong("id"), rs.getString("type"), rs.getString("order_id"),
160	                rs.getString("status"));
161	    }
162	}

